update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/strasbourg/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"La maintenance industrielle à Strasbourg et dans le Bas-Rhin","mecanisme":"Le Bas-Rhin aligne des industries que peu de départements réunissent : les quais du port rhénan, les brasseries de Schiltigheim, la pharmacie et la biotech d''Illkirch-Graffenstaden, l''automobile de Haguenau et de Molsheim. Notre hub de techniciens de Strasbourg travaille ces quatre univers avec les mêmes intervenants évalués.","cta":"Faire chiffrer ma maintenance à Strasbourg","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, nuits, week-ends et jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"10","libelle":"hubs de techniciens en France, dont un à Strasbourg, plus notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid"}]},{"type":"probleme","punchline":"Une ligne de conditionnement à l''arrêt en pleine saison, et votre meilleur électromécanicien qui vient de partir travailler de l''autre côté de la frontière. Le Bas-Rhin perd des techniciens avant de perdre des machines.","puces":[{"accroche":"La proximité allemande et bâloise tire les salaires techniques.","texte":"Le voisin recrute mieux payé : le bassin forme et voit partir, et vos postes restent ouverts."},{"accroche":"Les sites réglementés ne laissent aucune marge.","texte":"Pharmacie, chimie, agroalimentaire : protocole, traçabilité, accueil sécurité. L''improvisation se paie en non-conformité."},{"accroche":"L''automobile du Grand Est se transforme pendant qu''elle produit.","texte":"Les parcs machines changent en même temps que les modèles, et les compétences internes ne suivent pas toujours."},{"accroche":"La métallurgie use plus vite que tout le reste.","texte":"Presses, machines-outils, ponts roulants : les organes mécaniques s''y fatiguent à un rythme qui rend le préventif non négociable."},{"accroche":"Les quais du Rhin ne s''arrêtent pas.","texte":"Convoyage, levage, manutention portuaire : la disponibilité se joue tous les jours, week-ends compris."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Des techniciens salariés, évalués et encadrés","texte":", pas des profils trouvés dans l''urgence."},"benefice":"Vous ne subissez plus le marché de l''emploi transfrontalier pour tenir votre parc."},{"prestation":{"accroche":"L''entrée en site réglementé cadrée","texte":"plan de prévention, protocole de sécurité, habilitations à jour, coordination HSE."},"benefice":"Pharmacie, chimie et agroalimentaire gardent une documentation conforme à chaque visite."},{"prestation":{"accroche":"Automaticiens SIEMENS et Schneider, roboticiens ABB et Fanuc","texte":"en appui de l''équipe locale."},"benefice":"Les lignes cadencées de l''automobile retrouvent leur diagnostic sans attendre un spécialiste extérieur."},{"prestation":{"accroche":"Le champ technique complet","texte":"[mécanique](/expertises/mecanique/), [électricité](/expertises/electrique/), [électromécanique](/expertises/electromecanique/), [automatisme](/expertises/automatisme/), [hydraulique](/expertises/hydraulique/), [pneumatique](/expertises/pneumatique/), [soudure](/expertises/soudure/)."},"benefice":"Un seul contrat pour presses, robots, convoyeurs et utilités."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":", mobilisation depuis le hub de techniciens le plus proche."},"benefice":"Chaufferie, cogénération ou traitement des eaux : la nuit est couverte."},{"prestation":{"accroche":"Relais régionaux","texte":"[Alsace](/implantations/strasbourg/alsace/) pour le département, [Mulhouse](/implantations/strasbourg/mulhouse/) pour le Haut-Rhin."},"benefice":"Un industriel réparti entre les deux départements garde un seul interlocuteur."}],"prose":[{"texte":"Pour les gros travaux, transfert, rétrofit ou extension, l''offre [chantier](/offres/chantier/) prend le relais avec un chef de projet unique, de l''étude à la remise en route."}]},{"type":"deroule","etapes":[{"titre":"Le rappel dans l''heure","texte":"Vous décrivez la panne ou le besoin au 04 78 33 72 05. Un chargé d''affaires rappelle aux horaires ouvrés et qualifie la demande."},{"titre":"La préparation","texte":"Technicien choisi selon la machine et les habilitations, plan de prévention et accueil sécurité validés avec votre responsable de site."},{"titre":"L''entrée en zone","texte":"Protocole du site, consignation, protections, tenue adaptée à l''environnement réglementé."},{"titre":"La réparation","texte":"Réparer vite, puis établir la cause racine."},{"titre":"Les essais et la remise en production","texte":"Contrôles de bon fonctionnement, montée en cadence avec vos opérateurs."},{"titre":"Le compte rendu","texte":"Causes, analyse, actions, préconisations, versés dans votre GMAO. La visite suivante se prépare avec ce contenu."}]},{"type":"garanties","puces":[{"accroche":"La continuité, même en cas d''absence","texte":"départ, congé ou surcroît d''activité, le groupe fournit un profil équivalent briefé sur vos machines. Votre production ne dépend plus d''une seule personne."},{"accroche":"Le niveau prouvé, pas déclaré","texte":"entretien technique et entretien comportemental, un candidat sur dix retenu. Les résultats d''évaluation vous sont remis avant que le technicien franchisse votre portail."},{"accroche":"Un périmètre écrit dès le devis","texte":"équipements couverts, fréquences, indicateurs suivis, conditions de sortie. Le cadre protège les deux parties."}]},{"type":"cta","question":"Besoin de tenir vos lignes sans dépendre du marché de l''emploi transfrontalier ?","bouton":"Faire chiffrer ma maintenance à Strasbourg","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/strasbourg/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"18 à 25 techniciens sur plusieurs sites du Grand Est, depuis juin 2023","texte":"transition vers le véhicule électrique, partenariat reconduit","lienLibelle":"Étude de cas STELLANTIS : sites du Grand Est","lienHref":"/preuves/stellantis-grand-est/"},{"titre":"Un technicien à temps plein sur un parc d''usinage du Grand Est, en 2025","texte":"centres d''usinage, presses et commandes numériques, parc multimarques","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Montages, déplacements de machines et renfort technique ponctuel","texte":"chez un acteur de l''étanchéité et de l''isolation, sur l''année 2025","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Un technicien polyvalent intégré sur un site papier et emballage en forte cadence","texte":"2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Six techniciens sur l''installation et la mise en production d''un parc machines neuf","texte":", site automobile, depuis janvier 2023","lienLibelle":"Étude de cas EATON : mise en production","lienHref":"/preuves/eaton-mise-en-production/"}]},{"type":"objections","questions":[{"question":"Avez-vous vraiment des techniciens à Strasbourg, et intervenez-vous vers Haguenau, Molsheim, Colmar ou Mulhouse ?","reponse":"Oui. Strasbourg est l''un de nos 10 hubs de techniciens en France, épaulé par notre siège lyonnais et nos agences de Montréal, Dubaï et Madrid. Le hub rayonne sur le Bas-Rhin, de la zone portuaire aux bassins de Haguenau et de Molsheim, et travaille avec nos relais du Haut-Rhin jusqu''à Saint-Louis. Un industriel réparti sur les deux départements garde un contrat unique et des comptes rendus au même format."},{"question":"Dans quels délais intervenez-vous ?","reponse":"Nous ne vendons pas un délai standard : il varie selon la panne, l''accès au site et la pièce en cause. L''engagement tenu est le rappel dans l''heure aux horaires ouvrés, et l''astreinte 24/24 et 7/7 en option la nuit, le week-end et les jours fériés."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"Zéro arrêt est chiffré sur devis, avec trois niveaux de couverture et un engagement type de 6 mois renouvelable. Un site réglementé, avec ses protocoles d''entrée, ne se chiffre pas comme un atelier de mécanique : le devis le dit. Le diagnostic de départ est gratuit."},{"question":"Comment choisissez-vous le technicien qui vient chez nous ?","reponse":"Selon vos machines, les habilitations requises et l''historique du site. Tous ont passé un entretien technique et comportemental que 10 % des candidats réussissent. Sur un contrat suivi, vous gardez le même intervenant aussi longtemps que possible."},{"question":"Pouvez-vous accompagner un changement de parc machines ?","reponse":"Oui. Transfert, rétrofit, mise en production d''équipements neufs : un chef de projet unique porte le chantier, de l''étude au redémarrage. Sur un site qui produit pendant les travaux, le phasage et les fenêtres d''arrêt s''écrivent avant le premier démontage."},{"question":"Un atelier de vingt salariés vous intéresse-t-il autant qu''un site de groupe ?","reponse":"Oui. Nos clients vont de l''atelier de métallurgie aux sites de groupes industriels, en passant par la logistique et l''énergie. Le point commun est un besoin de fiabilité mesurable et un budget cadré, avec la même méthode quel que soit l''effectif."}]},{"type":"ctaFinal","question":"Besoin d''un mainteneur qui tienne le réglementé comme la mécanique lourde ?","bouton":"Faire chiffrer ma maintenance à Strasbourg","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/strasbourg/';
